fields.InputDefinition:
{
  "goal": "Open the application switcher dropdown next to the logo, switch to the 'Actions' application, and open the 'Explorer' nav item. Pages can take 10-30s to load in this resource-constrained environment — wait, don't navigate away. Click an action (card/row) to open its full record. The custom Action detail form should render with a header showing the action name plus Status and Type chips, and collapsible accordion sections including a 'Parameters' section (Input Parameters / Output Parameters grids) and, for AI-Generated actions, a 'Code & Generation' section. Expand the Parameters accordion and confirm the input/output parameter sub-sections render. Seeing the custom form with its status/type header and the Parameters accordion is success.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}
